// Copies that must never be remembered: password managers and other apps mark
// them with special clipboard formats. One list for every system.

/** Formats meaning "do not keep this": macOS (nspasteboard.org), Windows clipboard history, KDE/X11. */
export const CONCEALED_TYPES = [
  'org.nspasteboard.ConcealedType',
  'org.nspasteboard.TransientType',
  'org.nspasteboard.AutoGeneratedType',
  'com.agilebits.onepassword',
  'ExcludeClipboardContentFromMonitorProcessing',
  'CanIncludeInClipboardHistory',
  'CanUploadToCloudClipboard',
  'x-kde-passwordManagerHint',
];

/**
 * True when the clipboard's formats say the copy is secret or short-lived.
 * On Windows, "CanIncludeInClipboardHistory"/"CanUploadToCloudClipboard" only
 * count when their value is 0 (pass `values`); on KDE the hint's value is "secret".
 */
export function isConcealed(types: string[], values: Record<string, string | number | undefined> = {}): boolean {
  for (const t of types) {
    const name = t.replace(/^web\s+/, '').trim();
    if (/^org\.nspasteboard\.(Concealed|Transient|AutoGenerated)Type$/i.test(name)) return true;
    if (/^com\.agilebits\.onepassword$/i.test(name)) return true;
    if (name === 'ExcludeClipboardContentFromMonitorProcessing') return true;
    if (name === 'CanIncludeInClipboardHistory' || name === 'CanUploadToCloudClipboard') {
      const v = values[name];
      if (v === 0 || v === '0') return true;
      continue;
    }
    if (name === 'x-kde-passwordManagerHint') {
      const v = values[name];
      if (v === undefined || String(v).trim().toLowerCase() === 'secret') return true;
    }
  }
  return false;
}
